1	"use client";
2	
3	import { useId, useState } from "react";
4	import Link from "next/link";
5	import { ArrowRight, CalendarDays, Clock, LockKeyhole, Send } from "lucide-react";
6	import { cn } from "@/components/ui/cn";
7	import { herkunft } from "@/lib/herkunft";
8	import Textfeld from "@/components/formular/Textfeld";
9	import useFormular, { regel } from "@/components/formular/useFormular";
10	import { AbsendeKnopf, useAbsenden } from "@/components/formular/Absenden";
11	import { AutosaveHinweis, entwurfVorbelegen, useEntwurf } from "@/components/formular/Entwurf";
12	import { FeldMeldung } from "@/components/formular/FeldRahmen";
13	import { ErfolgsAnsicht, FormFehler } from "@/components/formular/Meldungen";
14	import { checkboxKlasse } from "@/components/formular/stil";
15	import AusfuellFortschritt, { pflichtErfuellt } from "@/components/formular/AusfuellFortschritt";
16	
17	const PFLICHT = ["vorname", "nachname", "email", "einwilligung"];
18	
19	/* Nächste Schritte nach dem Absenden – nur Aussagen, die die Website ohnehin macht (keine neuen Versprechen) */
20	const NAECHSTE = [
21	  "Ihre Anfrage liegt als Vorgang bei uns vor.",
22	  "Ein fester Ansprechpartner prüft sie und meldet sich bei Ihnen.",
23	  "Status, Dokumente und Nachrichten sehen Sie im Portal.",
24	];
25	
26	/**
27	 * Einheitliches Anfrageformular aller Zielgruppen.
28	 *
29	 * Schickt an POST /api/anfrage → Vorgang im Backoffice. Wer sich später
30	 * mit derselben E-Mail registriert, sieht den Vorgang samt Status im Portal.
31	 *
32	 * Props:
33	 *  typ        flaeche | agri | investor | projekt | reststrom | energiegemeinschaft | genossenschaft | kommune | carport | speicher | kontakt
34	 *  daten      fachliche Zusatzdaten (z. B. Ergebnis eines Rechners) – werden mitgeschickt
35	 *  felder     zusätzliche Kontaktfelder: firma, telefon, plz, ort, land, nachricht
36	 *  titel/text/button/erfolgText  Beschriftungen
37	 *  dunkel     für Navy-Flächen
38	 *
39	 * Darstellung (T5): eigene Inline-Prüfung beim Verlassen des Felds statt nativer Browser-Blasen, Fokus auf das
40	 * erste fehlerhafte Feld, Absende-Choreografie, Entwurf im Tab gesichert, Erfolg mit Fokus und Übergabe von
41	 * Name/E-Mail an die Registrierung (über sessionStorage, nicht über die URL). Server prüft verbindlich.
42	 */
43	
44	const SCHEMA = (felder, land) => ({
45	  vorname: [regel.pflicht("Bitte geben Sie Ihren Vornamen an."), regel.laenge(1, 80, "Der Vorname")],
46	  nachname: [regel.pflicht("Bitte geben Sie Ihren Nachnamen an."), regel.laenge(1, 80, "Der Nachname")],
47	  email: [regel.pflicht("Bitte geben Sie Ihre E-Mail-Adresse an, z. B. name@firma.de."), regel.email()],
48	  ...(felder.includes("telefon") ? { telefon: [regel.telefon()] } : {}),
49	  ...(felder.includes("plz") ? { plz: [regel.plz(land)] } : {}),
50	  ...(felder.includes("nachricht") ? { nachricht: [regel.laenge(0, 5000, "Die Nachricht")] } : {}),
51	  einwilligung: [regel.haken("Bitte stimmen Sie der Verarbeitung zu, damit wir Ihre Anfrage bearbeiten dürfen.")],
52	});
53	
54	export default function AnfrageFormular({
55	  typ = "kontakt",
56	  daten = {},
57	  felder = ["telefon", "nachricht"],
58	  titel,
59	  text,
60	  button = "Anfrage senden",
61	  erfolgText = "Danke! Ihre Anfrage ist eingegangen. Wir melden uns in der Regel innerhalb von zwei Werktagen.",
62	  rolle,
63	  className,
64	  dunkel = false,
65	  versprechen = "Wir melden uns in der Regel innerhalb von zwei Werktagen.",
66	}) {
67	  const id = useId();
68	  const [land, setLand] = useState("DE");
69	  const form = useFormular(
70	    { vorname: "", nachname: "", firma: "", email: "", telefon: "", plz: "", ort: "", land: "DE", nachricht: "", einwilligung: false, website: "" },
71	    // Schema hängt vom Land ab (PLZ-Länge) – neu bauen, wenn das Land wechselt
72	    SCHEMA_CACHE(felder.join(","), land)
73	  );
74	  const a = useAbsenden({ uebersetzen: fehlerUebersetzen });
75	  const [ergebnis, setErgebnis] = useState(null);
76	  const entwurf = useEntwurf(`anfrage-${typ}`, form.werte, { ohne: ["einwilligung", "website"], wiederherstellen: form.setzeAlle, aktiv: !ergebnis && a.status === "bereit" });
77	  const w = form.werte;
78	  const schema = SCHEMA_CACHE(felder.join(","), land);
79	  const erfuellt = pflichtErfuellt(schema, w, PFLICHT);
80	
81	  async function absenden(e) {
82	    e.preventDefault();
83	    if (a.status !== "bereit") return; // Doppelabsendung verhindern
84	    if (w.website) return; // Honeypot
85	    if (!form.pruefeAlles()) return;
86	    const kontakt = {};
87	    const erlaubt = ["vorname", "nachname", "email", ...["anrede", "firma", "telefon", "plz", "ort", "land"].filter((k) => felder.includes(k))];
88	    for (const k of erlaubt) {
89	      const v = w[k];
90	      if (v) kontakt[k] = String(v).trim();
91	    }
92	    const nachricht = felder.includes("nachricht") ? w.nachricht : "";
93	    const antwort = await a.los(
94	      async () => {
95	        const res = await fetch("/api/anfrage", {
96	          method: "POST",
97	          headers: { "Content-Type": "application/json" },
98	          body: JSON.stringify({
99	            typ,
100	            kontakt,
101	            daten: { ...daten, ...(nachricht ? { nachricht: String(nachricht) } : {}) },
102	            einwilligung: !!w.einwilligung,
103	            herkunft: safeHerkunft(),
104	          }),
105	        });
106	        const json = await res.json().catch(() => ({}));
107	        if (!res.ok || !json.ok) throw new Error(json.error || "Senden fehlgeschlagen");
108	        return json;
109	      },
110	      {
111	        haltezeit: 800,
112	        zuruecksetzen: false,
113	        danach: (json) => {
114	          entwurf.verwerfen();
115	          // Name/E-Mail für die Registrierung bereitlegen (nur in diesem Tab)
116	          entwurfVorbelegen("registrierung", { vorname: kontakt.vorname, nachname: kontakt.nachname, email: kontakt.email, firma: kontakt.firma, telefon: kontakt.telefon });
117	          setErgebnis(json);
118	        },
119	      }
120	    );
121	    // Netz-/Serverfehler: Der Knopf war während des Sendens deaktiviert, der Fokus ging verloren – zurück auf „Senden“,
122	    // damit ein erneuter Versuch per Enter/Leertaste möglich ist (die Meldung selbst sagt role="alert" an).
123	    if (!antwort) requestAnimationFrame(() => form.formRef.current?.querySelector('button[type="submit"]')?.focus());
124	  }
125	
126	  const feldProps = (k) => ({ ...form.feld(k), dunkel });
127	
128	  if (ergebnis) {
129	    const registrieren = `/registrieren?${new URLSearchParams({ rolle: rolle || rolleFuerTyp(typ), vorgang: ergebnis?.id || "" })}`;
130	    return (
131	      <div className={cn("rounded-3xl p-7 md:p-9", dunkel ? "bg-white/[0.06] ring-1 ring-white/10" : "bg-ov-50 ring-1 ring-ov-200", className)}>
132	        <ErfolgsAnsicht titel="Anfrage eingegangen" text={erfolgText} dunkel={dunkel}>
133	          {ergebnis?.id && (
134	            <p className={cn("mt-3 text-[13.5px]", dunkel ? "text-white/75" : "text-ink-600")}>
135	              Vorgangsnummer <span className="ov-num font-semibold">{ergebnis.id}</span>
136	            </p>
137	          )}
138	          {/* Erfolgs-Choreografie: Haken zeichnet sich (ErfolgsAnsicht), danach erscheinen die nächsten Schritte
139	              nacheinander (nur opacity/transform über .ov-ein; reduzierte Bewegung: sofort sichtbar). */}
140	          <div className="mt-6 grid items-start gap-3 sm:grid-cols-2">
141	            <Link
142	              href={registrieren}
143	              className="ov-ein group flex flex-col justify-between gap-3 rounded-2xl bg-ov-600 p-4 text-white shadow-gruen transition-colors hover:bg-ov-700 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-300 focus-visible:ring-offset-2 sm:col-span-2 sm:flex-row sm:items-center sm:p-5"
144	              style={{ "--ov-delay": "420ms" }}
145	            >
146	              <span className="min-w-0">
147	                <span className="block text-[15.5px] font-semibold">Status im Portal verfolgen</span>
148	                <span className="mt-0.5 block text-[13px] leading-snug text-white">Name und E-Mail-Adresse übernehmen wir – Sie vergeben nur noch ein Passwort.</span>
149	              </span>
150	              <span className="inline-flex h-10 w-10 shrink-0 items-center justify-center self-end rounded-full bg-white/15 sm:self-auto">
151	                <ArrowRight aria-hidden="true" className="ov-pfeil h-4 w-4" />
152	              </span>
153	            </Link>
154	            <Link
155	              href={`/termin${typ === "flaeche" ? "?herkunft=flaechencheck&art=beratung_video" : typ === "kontakt" ? "?herkunft=kontakt" : ""}`}
156	              className={cn(
157	                "ov-ein group flex items-center gap-3 rounded-2xl p-4 ring-1 ring-inset transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-500",
158	                dunkel ? "bg-white/[0.06] text-white ring-white/15 hover:bg-white/[0.1]" : "bg-white text-ink-900 ring-ink-200 hover:ring-ov-300"
159	              )}
160	              style={{ "--ov-delay": "520ms" }}
161	            >
162	              <span className={cn("flex h-10 w-10 shrink-0 items-center justify-center rounded-xl", dunkel ? "bg-ov-300/15 text-ov-300" : "bg-ov-50 text-ov-700")}>
163	                <CalendarDays aria-hidden="true" className="h-5 w-5" />
164	              </span>
165	              <span className="min-w-0 flex-1 text-[14.5px] font-semibold">Termin buchen</span>
166	              <ArrowRight aria-hidden="true" className={cn("ov-pfeil h-4 w-4 shrink-0", dunkel ? "text-ov-300" : "text-ov-700")} />
167	            </Link>
168	            <div
169	              className={cn("ov-ein rounded-2xl p-4 ring-1 ring-inset", dunkel ? "bg-white/[0.04] ring-white/10" : "bg-white/70 ring-ink-200/80")}
170	              style={{ "--ov-delay": "620ms" }}
171	            >
172	              <p className={cn("text-[12px] font-bold uppercase tracking-[0.12em]", dunkel ? "text-ov-300" : "text-ov-700")}>Was jetzt passiert</p>
173	              <ol className={cn("mt-2 space-y-1.5 text-[13.5px] leading-snug", dunkel ? "text-white/80" : "text-ink-700")}>
174	                {NAECHSTE.map((t, i) => (
175	                  <li key={t} className="flex gap-2">
176	                    <span aria-hidden="true" className={cn("ov-num font-bold", dunkel ? "text-ov-300" : "text-ov-700")}>{i + 1}</span>
177	                    <span className="min-w-0">{t}</span>
178	                  </li>
179	                ))}
180	              </ol>
181	            </div>
182	          </div>
183	        </ErfolgsAnsicht>
184	      </div>
185	    );
186	  }
187	
188	  const einwFehler = form.beruehrt.einwilligung ? form.fehler.einwilligung : "";
189	
190	  return (
191	    <form ref={form.formRef} onSubmit={absenden} noValidate className={cn("space-y-5", className)} aria-labelledby={titel ? `${id}-t` : undefined}>
192	      {titel && (
193	        <div>
194	          <p id={`${id}-t`} className={cn("font-display text-[22px] font-bold", dunkel ? "text-white" : "text-ink-900")}>{titel}</p>
195	          {text && <p className={cn("mt-1.5 text-[15px] leading-relaxed", dunkel ? "text-white/75" : "text-ink-600")}>{text}</p>}
196	        </div>
197	      )}
198	      <div className="grid gap-4 sm:grid-cols-2">
199	        <Textfeld id={`${id}-vn`} label="Vorname" pflicht autoComplete="given-name" maxLength={80} {...feldProps("vorname")} />
200	        <Textfeld id={`${id}-nn`} label="Nachname" pflicht autoComplete="family-name" maxLength={80} {...feldProps("nachname")} />
201	        {felder.includes("firma") && <Textfeld id={`${id}-fi`} label="Unternehmen / Betrieb" optional autoComplete="organization" maxLength={120} className="sm:col-span-2" {...feldProps("firma")} />}
202	        <Textfeld id={`${id}-em`} label="E-Mail" pflicht type="email" inputMode="email" autoComplete="email" autoCapitalize="none" spellCheck={false} maxLength={190} className={felder.includes("telefon") ? "" : "sm:col-span-2"} {...feldProps("email")} />
203	        {felder.includes("telefon") && <Textfeld id={`${id}-te`} label="Telefon" optional type="tel" inputMode="tel" autoComplete="tel" maxLength={40} {...feldProps("telefon")} />}
204	        {felder.includes("plz") && <Textfeld id={`${id}-plz`} label="PLZ" optional inputMode="numeric" autoComplete="postal-code" maxLength={10} {...feldProps("plz")} />}
205	        {felder.includes("ort") && <Textfeld id={`${id}-ort`} label="Ort" optional autoComplete="address-level2" maxLength={80} {...feldProps("ort")} />}
206	        {felder.includes("land") && (
207	          <Textfeld
208	            id={`${id}-la`}
209	            als="select"
210	            label="Land"
211	            className="sm:col-span-2"
212	            {...feldProps("land")}
213	            onChange={(e) => {
214	              form.setze("land", e.target.value);
215	              setLand(e.target.value);
216	            }}
217	          >
218	            <option value="DE">Deutschland</option>
219	            <option value="AT">Österreich</option>
220	            <option value="CH">Schweiz</option>
221	          </Textfeld>
222	        )}
223	        {felder.includes("nachricht") && <Textfeld id={`${id}-na`} als="textarea" label="Ihre Nachricht" optional rows={4} maxLength={5000} className="sm:col-span-2" {...feldProps("nachricht")} />}
224	      </div>
225	      {/* Honeypot */}
226	      <input type="text" name="website" tabIndex={-1} autoComplete="off" aria-hidden="true" className="hidden" value={w.website} onChange={(e) => form.setze("website", e.target.value)} />
227	      <div>
228	        <label className={cn("flex cursor-pointer items-start gap-3 text-[14px] leading-relaxed", dunkel ? "text-white/80" : "text-ink-700")}>
229	          <input
230	            type="checkbox"
231	            name="einwilligung"
232	            id={`${id}-ew`}
233	            data-feld="einwilligung"
234	            checked={!!w.einwilligung}
235	            onChange={(e) => {
236	              form.setze("einwilligung", e.target.checked);
237	              form.verlassen("einwilligung");
238	            }}
239	            aria-invalid={einwFehler ? true : undefined}
240	            aria-describedby={einwFehler ? `${id}-ew-fehler` : undefined}
241	            className={checkboxKlasse}
242	          />
243	          <span>
244	            Ich bin einverstanden, dass ÖkoInvest meine Angaben zur Bearbeitung der Anfrage verarbeitet. Details in der{" "}
245	            <Link href="/datenschutz" className={cn("font-medium underline underline-offset-2", dunkel ? "text-white" : "text-ink-900")}>Datenschutzerklärung</Link>.
246	            <span aria-hidden="true" className={dunkel ? "text-ov-300" : "text-ov-700"}> *</span>
247	          </span>
248	        </label>
249	        <FeldMeldung id={`${id}-ew`} fehler={einwFehler} dunkel={dunkel} />
